FE_DrawTextFromPointer::
	ld h, d
	ld l, e
	push bc
	jr FE_DrawText.next_char


FE_DrawText::
	ld a, $02
	ldh [rSVBK], a
	push de
	call FE_GetTextPointer
	pop de
	call FE_FarReadByte
	ld a, c
	add a, e
	ld b, a
	call FE_FarReadByte
	ld a, c
	add a, d
	ld d, b
	inc hl
	inc hl
	push hl
	ld a, d
	add a, a
	add a, a
	add a, a
	ld l, a
	ld h, $00
	add hl, hl
	add hl, hl
	ld b, $d4
	add hl, bc
	ld b, h
	ld c, l
	pop hl
	push bc
.next_char:
	push bc
	call FE_FarReadByte
	ld a, c
	pop bc
	cp $20
	jr z, .continue
	cp $86
	jr z, .else
	cp $87
	jr z, .done
	sub $20
	ld de, $6d84
	add a, e
	ld e, a
	ld a, $00
	adc a, d
	ld d, a
	push hl
	ld a, [de]
	ld l, a
	ldh a, [hFE_Scratch2]
	add a, l
	pop hl
	inc a
	ld [bc], a
	res 2, b
	ldh a, [hFE_Scratch2 + 1]
	ld [bc], a
	set 2, b
.continue:
	inc c
	jr .next_char

.else:
	pop bc
	ld a, $20
	add a, c
	ld c, a
	ld a, $00
	adc a, b
	ld b, a
	push bc
	jr .next_char

.done:
	pop bc
	ld a, $01
	ldh [rSVBK], a
	ret


FE_DrawTextOnMap::
	ld a, $02
	ldh [rSVBK], a
	call FE_GetTextPointer
	call FE_FarReadByte
	ld a, c
	add a, e
	ld b, a
	call FE_FarReadByte
	ld a, c
	add a, d
	ld d, b
	inc hl
	inc hl
	push hl
	ld a, d
	add a, a
	add a, a
	add a, a
	ld l, a
	ld h, $00
	add hl, hl
	add hl, hl
	ld b, $d4
	add hl, bc
	ld b, h
	ld c, l
	pop hl
	push bc
.loop:
	push bc
	call FE_FarReadByte
	ld a, c
	pop bc
	cp $20
	jr z, .continue
	cp $86
	jr z, .else
	cp $87
	jr z, .done
	sub $20
	ld de, $6ca7
	add a, e
	ld e, a
	ld a, $00
	adc a, d
	ld d, a
	push hl
	ld a, [de]
	add a, a
	ld l, a
	ldh a, [hFE_Scratch2]
	add a, l
	ld hl, $0020
	add hl, bc
	add a, $02
	ld [bc], a
	inc a
	ld [hl], a
	res 2, b
	res 2, h
	ldh a, [hFE_Scratch2 + 1]
	ld [bc], a
	ld [hl], a
	set 2, b
	pop hl
.continue:
	inc c
	jr .loop

.else:
